class Solution {
public:
    vector<ListNode*> splitCircularLinkedList(ListNode* list) {
        ListNode* slow = list;
        ListNode* fast = list;
        while (fast->next != list && fast->next->next != list) {
            slow = slow->next;
            fast = fast->next->next;
        }
        if (fast->next->next == list) fast = fast->next;
        ListNode* second = slow->next;
        slow->next = list;
        fast->next = second;
        return {list, second};
    }
};
